mapper.update:
UPDATE scm_purchase_plan
SET plan_number = #{planNumber},
    status = #{status},
    updated_at = #{updatedAt}
WHERE plan_id = #{planId} AND tenant_id = #{tenantId}

mapper.select:
SELECT plan_id, tenant_id, plan_number, status, created_at, updated_at
FROM scm_purchase_plan
WHERE tenant_id = #{tenantId} AND plan_id = #{planId}
